// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Token token;
    function setUp() public { c = new C(); token = new Token(); }
    function testFuzz_property(address actor, address[] calldata tos, uint256[] calldata vs) public {
        vm.assume(actor != address(0));
        vm.assume(tos.length > 0 && tos.length == vs.length);
        for (uint256 i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0));
        }
        vm.prank(actor);
        bool ok = c.transfer(address(token), tos, vs);
        assertTrue(ok, "successful transfer must return true");
    }
}

contract Token {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
